using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class BallChaseChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
 public static void VerifyModel(){var old=JsonUtility.FromJson<WorldPlayMemory>("{}");Require(old.Valid()&&old.Chase.games==0,"Old play saves rejected or mutated");var m=new ChaseMemory();m.Complete(12);Require(m.Valid()&&m.games==1&&m.bestDistance==12,"Chase outcome not bounded");m.bestDistance=float.NaN;Require(!m.Valid(),"Invalid chase distance accepted");var s=new SliceState();s.WorldPlay.Chase.Complete(20);s.Hybrid.receipt=new ActionReceipt{action=CreatureAction.PlayWithToy,chased=true};Require(s.Valid(),"Chase lesson invalid");s.Hybrid.receipt.fetched=true;Require(!s.Valid(),"Fetch and chase confused");s.Hybrid.receipt.fetched=false;Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(s)).WorldPlay.Chase.games==1,"Chase history did not save");Debug.Log("BWVR_CHASE_MODEL_PASS: historical saves, bounded history, typed receipts and round trip");}
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();slice.SetSanctuaryOpen(false);var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var nav=god.GetComponent<IslandNavigator>();var ball=slice.GetComponentInChildren<BeachBall>();var item=ball.GetComponent<CarryItem>();var field=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)field.GetValue(slice);var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);Require(held.All(i=>i==null),"Release objects before testing");var godAt=god.transform.position;var godRot=god.transform.rotation;var at=ball.Bowling.Start;var forward=ball.Bowling.Forward;var right=ball.Bowling.Right;var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.1f,playPreference=1};field.SetValue(slice,test);god.NewSeason();var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);
  void Position(Vector3 foot){Require(nav.world.Sample(foot,nav.profile,5,out var sample),"No test path");god.transform.position=nav.world.ProjectFoot(sample,nav.profile);god.transform.rotation=Quaternion.LookRotation(forward);nav.ResetRoute();}
  void Hold(Vector3 foot){var projected=nav.world.Terrain.Project(foot);ball.transform.position=projected+Vector3.up*nav.world.Scale*8;}
  void Tick(float dt){ball.Advance(dt,false);god.Tick(dt);}
  try{
   Position(at);ball.ReturnHome();var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);Require((bool)typeof(QuestSlice).GetMethod("TryGrab",Flags).Invoke(slice,new object[]{1,item}),"Native ball grab failed");
   Hold(at-forward*20*nav.world.Scale);for(int i=0;i<24;i++){test.Hybrid.time+=.05f;ball.Advance(.05f,false);}Require(!ball.Chase.Ready,"Unseen held ball invited chase");Hold(at+forward*20*nav.world.Scale);for(int i=0;i<24;i++){test.Hybrid.time+=.05f;ball.Advance(.05f,false);}Require(ball.Chase.Ready,"Visible held ball did not invite chase");
   foreach(var a in cooldowns.Keys)if(a!=item.GetComponent<CreatureAffordance>())a.cooldown=test.Hybrid.time+200;
   bool selected=false;for(int i=0;i<240;i++){Hold(at+forward*(20+Mathf.Min(i*.08f,16))*nav.world.Scale);Tick(.05f);selected|=mind.Current==CreatureCuriosity.Phase.ChaseBall;Require(held[1]==item&&item.held&&mind.Holding==null,"Creature took player-held toy");if(ball.Chase.Distance>=10&&i>80)break;}
   Require(selected&&ball.Chase.Active&&ball.Chase.Distance>=8,"Utility-selected chase did not move: "+mind.Current+" distance "+ball.Chase.Distance+" owner "+god.Owner+" / "+god.Explanation);
   float distance=ball.Chase.Distance;var position=god.transform.position;test.paused=true;ball.Advance(1,true);god.Tick(1);Require(ball.Chase.Distance==distance&&god.transform.position==position,"Paused chase moved");test.paused=false;
   // Native slow release ends the bout without turning it into a throw.
   var history=(ThrowMotion[])typeof(QuestSlice).GetField("throwMotion",Flags).GetValue(slice);history[1].Reset();typeof(QuestSlice).GetMethod("Release",Flags).Invoke(slice,new object[]{1,new Ray(ball.transform.position+Vector3.up*.1f,Vector3.down)});god.Tick(.05f);
   Require(test.WorldPlay.Chase.games==1&&test.Hybrid.receipt.eligible&&test.Hybrid.receipt.chased&&!test.Hybrid.receipt.fetched,"Successful release did not create exactly one chase lesson");float pref=test.WorldPlay.Chase.preference;Require(god.Feedback(true)&&!god.Feedback(true)&&test.WorldPlay.Chase.preference>pref,"Chase feedback missing or repeatable");Require(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Played save invalid");for(int i=0;i<10;i++)Tick(.05f);Require(test.WorldPlay.Chase.games==1,"Release counted twice");
   god.Interrupt("Chase interruption check");ball.Chase.Reset();Position(at);Hold(at+forward*20*nav.world.Scale);held[1]=item;item.held=true;item.GetComponent<Collider>().enabled=false;for(int i=0;i<24;i++){test.Hybrid.time+=.05f;ball.Advance(.05f,false);}Require(mind.TryBeginChase(item.GetComponent<CreatureAffordance>()),"Second chase setup failed");god.Interrupt("Player canceled");Require(!ball.Chase.Active&&held[1]==item&&item.held&&test.WorldPlay.Chase.games==1,"Interrupted chase stole ball or rewarded");
   // Stationary bait may invite an approach, but cannot farm successful play rewards.
   ball.Chase.Reset();Position(at);Hold(at+forward*20*nav.world.Scale);for(int i=0;i<24;i++){test.Hybrid.time+=.05f;ball.Advance(.05f,false);}Require(mind.TryBeginChase(item.GetComponent<CreatureAffordance>()),"Stationary setup failed");for(int i=0;i<100;i++){ball.Advance(.05f,false);test.Hybrid.time+=.05f;mind.Tick(.05f,test,false);}held[1]=null;item.held=false;mind.Tick(.05f,test,false);Require(test.WorldPlay.Chase.games==1&&!ball.Chase.Active,"Stationary bait farmed a reward");
   Debug.Log("BWVR_CHASE_PLAY_PASS: unseen exclusion, native pickup, visible invitation, utility-selected grounded follow, exclusive player carry, pause, native release, one-shot typed feedback/save and cancellation. Distance="+distance);
  }finally{god.Interrupt("Chase QA finished");held[1]=null;item.held=false;item.GetComponent<Collider>().enabled=true;ball.ReturnHome();field.SetValue(slice,original);god.NewSeason();foreach(var pair in cooldowns)pair.Key.cooldown=pair.Value;god.transform.SetPositionAndRotation(godAt,godRot);nav.ResetRoute();ball.ResetWorld();}
 }
}
}
